        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Right index finger lesion bleeding"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reported intermittent bleeding, especially with using the till and handling notes; recurrent minor-trauma bleeding affects work function."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Hand function and range of motion"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Grip strength within normal limits bilaterally; able to make a full fist and open the hand against resistance. Fine motor function intact. Full active and passive range of motion at right index PIP, DIP, and MCP joints without pain. Sensation intact; capillary refill normal; hand function preserved."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Gait and posture"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Independent gait with normal pattern and stable stance; able to fully weight bear. No issues noted while walking to the door."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Fatigue"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient briefly reported feeling a bit tired lately; full evaluation deferred due to time."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "completed",
        "medicationCodeableConcept": {
          "text": "Boostrix (dTpa vaccine)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "0.5 mL intramuscularly, given in the left deltoid",
            "route": {
              "text": "intramuscular"
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 0.5,
                  "unit": "mL"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "completed",
        "medicationCodeableConcept": {
          "text": "Inactivated influenza vaccine, 2025 season"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "0.5 mL intramuscularly, given in the right deltoid",
            "route": {
              "text": "intramuscular"
            },
